def find_path(graph, start, goal):
    # Initialize the path and visited set
    path = []
    visited = set()

    def explore(node):
        if node not in visited:
            visited.add(node)
            path.append(node)
            if node == goal:
                return True
            for neighbor in graph.get(node, []):
                if explore(neighbor):
                    return True
            path.pop()
        return False

    if not explore(start):
        return None

    return path
